/**
 * camelcase 변경
 * @param str
 * @returns
 */
/**
 * @method
 * @name camelize
 * @description desc
 * @param {string} str desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.camelize = function(str) {
    return str.replace(/_/gi, ' ').replace(/\W+(.)/g, function(match, chr) {
        return chr.toUpperCase();
    });
};
